head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS10000.xml';
scwin.vMktactCd = "";
scwin.vCheck_BndApplId = '';
scwin.vBndApplId = ""; //채권신청ID
scwin.vBndListProcsTpCd = "1"; //채권처리구분(1:신청,2:접수)
scwin.vRowCount = 0;
scwin.fn_GetPar, scwin.fn_SetPar, scwin.vSelObj;
scwin.processGp; //접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.vStripAmtCfm = '';
scwin.vRegYn = 'N';
scwin.vRowPos = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetMktactCd
 * 설명      : 채권시장조치구분코드 설정
 ***********************************************/
scwin.fn_SetMktactCd = function() {
    scwin.vMktactCd = "401";
};


/********************************************** 
 * 함수명   : fn_list_sync
 * 설명      : 목록조회
 ***********************************************/
scwin.fn_list_sync = function() {
    var param = '';
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    param += "&{P}V_MKTACT_CD=" + scwin.vMktactCd;
    var dsNm = 'BNS_APPL_ACPT_LIST';
    var qryId = 'lds.stf.bnscommon.select.listApplAndAcpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    if (scwin.vBndListProcsTpCd == '1') {
        $c.cm.ShowWin(grd_List1);
    } else {
        $c.cm.ShowWin(grd_List2);
    }
};



/********************************************** 
 * 함수명   : fn_dtl_sync
 * 설명      : 상세조회
 ***********************************************/
scwin.fn_dtl_sync = function() {
    var param = '';
    param += "&{P}V_BND_APPL_ID=" + scwin.vBndApplId;
    param += "&{P}V_BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;

    //상세조회
    var dsNm = 'BNS_STRIP_INFO';
    var qryId = 'lds.stf.bnschg.select.readStripIsuInfo';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);

    //이자분리내역
    qryId = 'lds.stf.bnschg.select.listStripIntSplit';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IntSplit, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_InputCheck
 * 설명      : 필수 입력 값을 체크한다. 
 ***********************************************/
scwin.fn_InputCheck = function() {
    if ($c.stf.getObjectValue(edt_StrtDd) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '적용일'));
        edt_StrtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
        return false;
    }
    if ($c.stf.getObjectValue(edt_SprtParAmt) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '신청액면금액'));
        edt_SprtParAmt.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_PrnpIsuNm) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '원금분리채권 종목기준명'));
        txb_PrnpIsuNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_PrnpBndClssNm) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '원금분리채권 채권분류'));
        txb_PrnpBndClssNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_PrnpCoupnRt) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '원금분리채권 표면이자율'));
        edt_PrnpCoupnRt.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_BndFstSprtDd) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '원금분리채권 최초분리일'));
        edt_BndFstSprtDd.focus();
        return false;
    }
    if ($c.bns.fn_CheckDateObj(edt_BndFstSprtDd, "원금분리채권 최초분리일")) {
        return false;
    }
    if ($c.stf.getObjectValue(txb_IntIsuNm) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '이자분리채권 종목기준명'));
        txb_IntIsuNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_IntBndClssNm) == '') {
        $c.win.alert($c.stf.getMessageParam('MSG-A005', '이자분리채권  채권분류'));
        txb_IntBndClssNm.focus();
        return false;
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_StrtDddCheck
 * 설명      :  접수/처리완료 시, 해당종목의 조치일이 이미 같은일자로 시장조치 대기중인지 체크
 ***********************************************/
scwin.fn_StrtDddCheck = function() {
    vIsuCd = dts_IsuInfo.getCellData(1, "STD_CD");
    if (scwin.processGp == '1') {
        //접수처리시
        $c.bns.fn_CheckAcptStripStrtDd(scwin.vScrenID, dts_CheckAcptStrtDd, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId, vIsuCd, scwin.processGp);
        if (dts_CheckAcptStrtDd.getTotalRow() > 0) {
            if (scwin.vCheck_BndApplId == '') {
                $c.win.alert("상환일(" + $c.stf.getObjectValue(edt_StrtDd) + ") 만료에 의한 자동상장폐지 종목입니다.");
            } else {
                $c.win.alert("이미 접수번호 " + scwin.vBndApplId + ": 적용일 " + $c.stf.getObjectValue(edt_StrtDd) + " " + scwin.vMktactCd + "(으)로 처리중이므로 적용일을 다시 입력하십시오.");
            }
            return false;
        }
    } else if (scwin.processGp == '3') {
        //처리완료시
        $c.bns.fn_CheckAcptProcStrtDd(scwin.vScrenID, dts_CheckAcptStrtDd, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId, vIsuCd, scwin.processGp);
        if (dts_CheckAcptStrtDd.getTotalRow() > 0) {
            $c.win.alert("이미 접수번호 " + scwin.vBndApplId + ": 적용일 " + $c.stf.getObjectValue(edt_StrtDd) + " " + scwin.vMktactCd + "(으)로 처리중이므로 적용일을 다시 입력하십시오.");
            return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : fn_Acpt
 * 설명       : 신청데이터를 접수 처리한다.
 ***********************************************/
scwin.fn_Acpt = function() {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return;

    //적용일,매매일,마감일 체크		
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId) > 0) return;

    //해당종목의 조치일이 이미 같은일자로 시장조치 대기중인지 체크
    //if (fn_StrtDddCheck() == false) return;

    //복수조치 체크		
    if ($c.bns.fn_CheckMultActImpsblRule(scwin.vScrenID, dts_Temp, $c.stf.getObjectValue(txb_StdCd), scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //접수		
    var hasAttachDoc = dts_List.getCellData(1, "HAS_ATTACH_DOC");
    if (!$c.bns.fn_EndConfirm(hasAttachDoc, '접수')) return;
    var param = 'BND_MKTACT_TP_CD=' + scwin.vMktactCd;
    var url = "/bns/Strip.do?method=processApplAcpt";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    dts_IsuInfo.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_ProcsComplt
 * 설명       : 처리완료 및 수정을 처리한다.
 ***********************************************/
scwin.fn_ProcsComplt = function() {
    //필수입력값 체크
    if (scwin.fn_InputCheck() == false) return;

    //적용일,매매일,마감일,채권마감 체크		
    if ($c.bns.fn_CheckCmData(scwin.vScrenID, dts_CheckCmData, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId) > 0) return;

    //해당종목의 조치일이 이미 같은일자로 시장조치 대기중인지 체크
    //if (fn_StrtDddCheck() == false) return;
    //복수조치 체크		
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd(scwin.vScrenID, dts_Temp, $c.stf.getObjectValue(txb_StdCd), scwin.vMktactCd, $c.stf.getObjectValue(edt_StrtDd)) > 0) return;

    //처리완료,수정
    var hasAttachDoc = dts_List.getCellData(1, "HAS_ATTACH_DOC");
    var url;
    if (scwin.processGp == '4') {
        //접수 후 수정 및 반송시 체크한다.			
        if ($c.bns.fn_CheckModAndRet(scwin.vScrenID, dts_CheckCmData, scwin.vBndApplId) > 0) return;
        if (!confirm("수정처리 하시겠습니까?")) return;
    } else {
        if (!$c.bns.fn_EndConfirm(hasAttachDoc, '처리완료')) return;
        //스트립 추가/재결합 처리완료 여부 확인			
        $c.bns.fn_CheckAcptProcStripProcCfm(dts_StripProcCfm, $c.stf.getObjectValue(edt_StrtDd), scwin.vBndApplId, $c.stf.getObjectValue(txb_StdCd), scwin.vBndListProcsTpCd);
        //추가상장/스트립 동시 시장조치 금액확인 팝업 호출
        var cnt = dts_StripProcCfm.getCellData(1, 'VALUE');
        if (cnt > 0) {
            scwin.fn_GetPar = fn_GetAddAndStripMktactAmtCfm;
            scwin.fn_SetPar = fn_SetRegYnReturn;
            $c.bns.fn_PopAddAndStripMktactAmtCfm(grd_List1);
            if (scwin.vRegYn != "Y") return; // jackal_15_01_08
        }
    }

    //변경된 데이터가 없더라도 데이터셋 전송하여 처리완료 진행
    dts_IsuInfo.UseChangeInfo = "False";
    if (scwin.processGp == '4') {
        url = "/bns/Strip.do?method=updateAcpt";
    } else {
        url = "/bns/Strip.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    var param = "REG_YN=" + scwin.vRegYn;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyValue = "JSP(I:pInput=dts_IsuInfo)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_GetCommonKey
 * 설명       : 팝업에 넘길 키데이터를 정의한다.
 ***********************************************/
scwin.fn_GetCommonKey = function(arrPar) {
    arrPar[0] = {
        //첨부문서 목록 팝업	
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISU_CD: dts_IsuInfo.getCellData(1, "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetReturn
 * 설명       : 반송 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetReturn = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        ISUR_NM: dts_IsuInfo.getCellData(1, "ISUR_NM"),
        ISU_NM: dts_IsuInfo.getCellData(1, "ISU_NM")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetReturn
 * 설명       : 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetReturn = function(arrPar) {
    if ("Y" == arrPar[0].SUCCESS_YN) {
        scwin.fn_list_sync();
    }
};



/********************************************** 
 * 함수명   : fn_GetParApprovFileWrt
 * 설명       : 결재파일생성 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParApprovFileWrt = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.vBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_StripIsuDetail
 * 설명       : 스트립종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_StripIsuDetail = function(arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.vBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_GetAddAndStripMktactAmtCfm
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetAddAndStripMktactAmtCfm = function(arrPar) {
    arrPar[0] = {
        VIEW_YN: scwin.vStripAmtCfm,
        BND_APPL_ID: dts_IsuInfo.getCellData(1, "BND_APPL_ID"),
        BND_LIST_PROCS_TP_CD: dts_IsuInfo.getCellData(1, "BND_LIST_PROCS_TP_CD"),
        BND_MKTACT_TP_CD: scwin.vMktactCd,
        ISU_CD: dts_IsuInfo.getCellData(1, "STD_CD"),
        ADD_ISU_AMT: dts_IsuInfo.getCellData(1, "ADD_ISU_AMT")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetAddAndStripMktactAmtCfm
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에서 넘긴 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetAddAndStripMktactAmtCfm = function(arrPar) {

};

/********************************************** 
 * 함수명   : fn_SetRegYnReturn
 * 설명       : 추가상장/스트립 동시 시장조치 금액확인 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetRegYnReturn = function(arrPar) {
    scwin.vRegYn = arrPar[0].REG_YN;
    dts_IsuInfo.setCellData(1, 'ADD_LIST_APPL_ID', arrPar[0].ADD_LIST_APPL_ID);
    dts_IsuInfo.setCellData(1, 'STRIP_APPL_ID', arrPar[0].STRIP_APPL_ID);
    dts_IsuInfo.setCellData(1, 'ADD_STRIP_APPL_ID', arrPar[0].ADD_STRIP_APPL_ID);
    dts_IsuInfo.setCellData(1, 'AFCHG_ISU_AMT', arrPar[0].AFCHG_ISU_AMT);
    dts_IsuInfo.setCellData(1, 'AFCHG_LIST_AMT', arrPar[0].AFCHG_LIST_AMT);
    dts_IsuInfo.setCellData(1, 'AFCHG_STRIP_NSPRT_BAL', arrPar[0].AFCHG_STRIP_NSPRT_BAL);
};


/********************************************** 
 * 함수명   : fn_GetParBndBasNm
 * 설명       : 종목기준명 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParBndBasNm = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: dts_IsuInfo.getCellData(1, "ISUR_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParPrnpBndBasNm
 * 설명       : 종목기준명 팝업에서 받은 데이터를 원금분리채권에 설정한다.
 ***********************************************/
scwin.fn_SetParPrnpBndBasNm = function(arrPar) {
    if (typeof(arrPar[0].BAS_ISU_NM) != 'undefined') {
        $c.stf.setObjectValue(txb_PrnpIsuNm, arrPar[0].BAS_ISU_NM);
        dts_IsuInfo.setCellData(1, 'PRNP_ISU_ABBRV', arrPar[0].BAS_ISU_ABBRV);
        dts_IsuInfo.setCellData(1, 'PRNP_ISU_ENG_NM', arrPar[0].BAS_ISU_ENG_NM);
        dts_IsuInfo.setCellData(1, 'PRNP_ISU_ENG_ABBRV', arrPar[0].BAS_ISU_ENG_ABBRV);
    }
};


/********************************************** 
 * 함수명   : fn_SetParIntBndBasNm
 * 설명       : 종목기준명 팝업에서 받은 데이터를 이자분리채권에 설정한다.
 ***********************************************/
scwin.fn_SetParIntBndBasNm = function(arrPar) {
    if (typeof(arrPar[0].BAS_ISU_NM) != 'undefined') {
        $c.stf.setObjectValue(txb_IntIsuNm, arrPar[0].BAS_ISU_NM);
        dts_IsuInfo.setCellData(1, 'INT_ISU_ABBRV', arrPar[0].BAS_ISU_ABBRV);
        dts_IsuInfo.setCellData(1, 'INT_ISU_ENG_NM', arrPar[0].BAS_ISU_ENG_NM);
        dts_IsuInfo.setCellData(1, 'INT_ISU_ENG_ABBRV', arrPar[0].BAS_ISU_ENG_ABBRV);
    }
};



/********************************************** 
 * 함수명   : fn_GetParIsuDtlAndMktactDtl
 * 설명       : 시장조치상세내역 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDtlAndMktactDtl = function(arrPar) {
    arrPar[0] = {
        STD_CD: $c.stf.getObjectValue(txb_StdCd),
        STRT_DD: ''
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/********************************************** 
 * 함수명   : fn_InitData
 * 설명       : 데이터 초기화 한다.
 ***********************************************/
scwin.fn_InitData = function() {
    dts_IsuInfo.removeAll();
    dts_IntSplit.removeAll();
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(lbl_ReturnPos, false);
    $c.stf.showObj(btn_TeamleadrConfrm, false);
    $c.stf.showObj(img_PrnpIsuNm, false);
    $c.stf.showObj(img_IntIsuNm, false);

    //패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Acpt); //접수
    $c.bns.BnsPanelToGroupBox(pnl_Req); //신청
    $c.bns.BnsPanelToGroupBox(pnl_DtlInfo); //상세
    tab_List.setSelectedTabIndex(1);
    scwin.fn_SetMktactCd(); //시장조치구분 설정	
    scwin.fn_list_sync(); //목록 조회

    //팀장확인데이터셋설정	

    //dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Temp.insertRow();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.tab_List_OnSelChanged = function(nIndex) {
    scwin.vBndListProcsTpCd = nIndex;
    scwin.fn_InitData();
    if (scwin.vBndListProcsTpCd == 2) {
        txb_Dtl.setValue("스트립신규 접수내역");
    } else {
        txb_Dtl.setValue("스트립신규 신청내역");
    }
    scwin.fn_list_sync();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (row > 0) {
        scwin.vRegYn = '';
        scwin.vBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
        vProcsStatCd = dts_List.getCellData(row, "PROCS_STAT_CD");
        if (vProcsStatCd == '2' || vProcsStatCd == '3') {
            btn_Proc.src = "../img/bns/btn_20_d.gif";
            btn_Proc.setDisabled(true);
        } else {
            btn_Proc.src = "../img/bns/btn_20.gif";
            btn_Proc.setDisabled(false);
        }
        scwin.fn_dtl_sync();
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (scwin.vBndListProcsTpCd == 2) {
        $c.cm.CloseWin(rowcount, grd_List2);
        //접수,수정,처리완료,팀장확인 시 해당 ROW로 이동
        $c.bns.fn_RowPos(dts_List, scwin.vRowPos);
    } else {
        $c.cm.CloseWin(rowcount, grd_List1);
    }
};
scwin.dts_IsuInfo_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    if (rowcount > 0) {
        //이자분리채권 종목기준명 설정
        //setObjectValue(txb_IntIsuNm, '');

        //당일 스트립설정
        if (dts_IsuInfo.getCellData(1, 'TDD_ADD_LIST_MKTACT_YN') == 'Y') {
            $c.stf.setObjectValue(chk_TddAddListMktactYn, 'Y');
        } else {
            $c.stf.setObjectValue(chk_TddAddListMktactYn, 'N');
        }

        //원금분리채권 종목명 설정
        if (dts_IsuInfo.getCellData(1, 'PRNP_ISU_NM') != '') {
            $c.stf.setObjectValue(txb_PrnpIsuNm1, dts_IsuInfo.getCellData(1, 'PRNP_ISU_NM') + ' ' + dts_IsuInfo.getCellData(1, 'PRNP_UNQ_ISU_NM'));
        } else {
            $c.stf.setObjectValue(txb_PrnpIsuNm1, '');
        }
    }
};
